mapper.select:
SELECT s.*, e.name as employee_name, e.employee_no, d.unit_name as dept_name, sh.shift_name, sh.shift_code FROM att_schedule s LEFT JOIN hr_employee e ON s.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id LEFT JOIN att_shift sh ON s.shift_id = sh.id WHERE 1 = 1
AND e.dept_id IN
#{orgId}
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND s.schedule_date >= #{startDate}
AND s.schedule_date <= #{endDate}
ORDER BY e.id, s.schedule_date
